def _sr_controller_ablation_allows_inactive_beam(contract: str) -> bool:
    """Return whether an explicit SR ablation may turn beam search off."""

    return (
        str(contract).strip().lower()
        == SR_CONTROLLER_ABLATION_CONTRACT_NOVELTY_PRUNE_BEAM_CONTROLS_V1
    )


def _sr_escape_record_id_for_mapping(record: Mapping[str, Any]) -> str:
    key = _batch_admission_record_key(record)
    return sr_escape_record_id(str(key[2]), int(key[0]), int(key[1]))


def _sr_active_correction_selection_mode(decision_kind: str) -> str:
    """Return the stable no-admission selection label for an SR correction."""

    resolved = str(decision_kind)
    if resolved == "active_stationarity_correction":
        return "sr_snake_active_stationarity_correction_v1"
    if resolved == "active_only_correction":
        return "sr_snake_active_only_correction_v1"
    raise ValueError(f"Unknown SR active-correction decision kind: {resolved!r}")


def _sr_escape_no_singleton_log_fields(
    controller: Mapping[str, Any],
) -> dict[str, Any]:
    """Return compact certificate attribution for an SR no-singleton stop."""

    reachable_record_ids = controller.get("reachable_record_ids", [])
    ordinary_live_ids = controller.get("ordinary_model_live_record_ids", [])
    contradicted_ids = controller.get("contradicted_ordinary_record_ids", [])
    certificate_counts = controller.get("certificate_kind_counts", {})
    unresolved_counts = controller.get(
        "unresolved_certificate_reason_counts", {}
    )
    return {
        "record_id": controller.get("record_id"),
        "certificate_record_id": controller.get("certificate_record_id"),
        "actionable": bool(controller.get("actionable", False)),
        "consumes_singleton": bool(
            controller.get("consumes_singleton", False)
        ),
        "reachable_population_complete": bool(
            controller.get("reachable_population_complete", False)
        ),
        "reachable_population_digest": controller.get(
            "reachable_population_digest"
        ),
        "state_stationarity_certified": bool(
            controller.get("state_stationarity_certified", False)
        ),
        "state_stationarity_blocker": controller.get(
            "state_stationarity_blocker"
        ),
        "reachable_record_count": int(len(reachable_record_ids)),
        "certificate_kind_counts": dict(certificate_counts),
        "unresolved_certificate_reason_counts": dict(unresolved_counts),
        "ordinary_model_live_record_count": int(len(ordinary_live_ids)),
        "contradicted_ordinary_record_count": int(len(contradicted_ids)),
    }


_SR_ORDINARY_MODEL_LIVE_RECEIPT_SCHEMA = "sr_ordinary_model_live_receipt_v1"


def _sr_ordinary_model_contradiction_receipt(
    *,
    state_fingerprint: str,
    record_id: str,
    guard_payload: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Retire a predicted-only ordinary model after an exact contradiction.

    Mapping/nonfinite failures never create a contradiction.  A finite exact
    comparison retires the model only when the upper bound on its mapped-seed
    reduction is nonpositive.  The receipt is scoped to the current physical
    state fingerprint, so any genuine state transition naturally restores a
    fresh model status.
    """

    if str(guard_payload.get("status", "")) != "rejected":
        return None
    failure_kind_raw = guard_payload.get("transaction_failure_kind")
    if failure_kind_raw is not None and str(failure_kind_raw):
        return None
    if str(guard_payload.get("schema", "")) != (
        "route_a_joint_step_warm_start_v1"
    ):
        return None
    comparison_width_raw = guard_payload.get("energy_comparison_width")
    if not isinstance(comparison_width_raw, Mapping):
        return None
    comparison_width = copy.deepcopy(dict(comparison_width_raw))
    if str(comparison_width.get("schema", "")) != (
        "sr_simultaneous_energy_comparison_width_v1"
    ):
        return None
    expected_event_schema = "route_a_exact_joint_step_seed_guard_v1"
    if str(comparison_width.get("comparison_event_schema", "")) != (
        expected_event_schema
    ) or str(guard_payload.get("comparison_event_schema", "")) != (
        expected_event_schema
    ):
        return None
    try:
        exact_gain = float(guard_payload.get("mapped_seed_exact_gain"))
        predicted_gain = float(
            guard_payload.get("mapped_seed_predicted_reduction")
        )
        numerical_width = float(
            comparison_width.get("numerical_energy_comparison_width")
        )
        optimizer_allowance = float(
            comparison_width.get("optimizer_reproducibility_allowance")
        )
        aggregate_width = float(
            comparison_width.get("aggregate_simultaneous_comparison_width")
        )
        top_numerical_width = float(
            guard_payload.get("numerical_energy_comparison_width")
        )
        top_optimizer_allowance = float(
            guard_payload.get("optimizer_reproducibility_allowance")
        )
        top_aggregate_width = float(
            guard_payload.get("aggregate_simultaneous_comparison_width")
        )
        guard_raw = guard_payload.get("guard")
        if not isinstance(guard_raw, Mapping):
            return None
        guard_tolerance = float(guard_raw.get("guard_tolerance"))
    except (TypeError, ValueError):
        return None
    comparison_values = (
        numerical_width,
        optimizer_allowance,
        aggregate_width,
        top_numerical_width,
        top_optimizer_allowance,
        top_aggregate_width,
        guard_tolerance,
    )
    if any(
        not math.isfinite(value) or value < 0.0
        for value in comparison_values
    ):
        return None
    width_scale = float(max(1.0, *(abs(value) for value in comparison_values)))
    width_tolerance = float(
        128.0 * np.finfo(float).eps * width_scale
    )
    if (
        abs(aggregate_width - (numerical_width + optimizer_allowance))
        > width_tolerance
        or abs(top_numerical_width - numerical_width) > width_tolerance
        or abs(top_optimizer_allowance - optimizer_allowance)
        > width_tolerance
        or abs(top_aggregate_width - aggregate_width) > width_tolerance
        or abs(guard_tolerance - numerical_width) > width_tolerance
    ):
        return None
    if (
        not str(state_fingerprint)
        or not str(record_id)
        or not math.isfinite(exact_gain)
        or not math.isfinite(predicted_gain)
        or predicted_gain <= 0.0
    ):
        return None
    exact_gain_upper_bound = float(exact_gain + aggregate_width)
    if exact_gain_upper_bound > 0.0:
        return None
    return {
        "schema": _SR_ORDINARY_MODEL_LIVE_RECEIPT_SCHEMA,
        "state_fingerprint": str(state_fingerprint),
        "record_id": str(record_id),
        "model_status_before": "live",
        "model_status_after": "contradicted",
        "contradiction_reason": (
            "exact_mapped_seed_reduction_upper_bound_nonpositive"
        ),
        "mapped_seed_predicted_reduction": float(predicted_gain),
        "mapped_seed_exact_gain": float(exact_gain),
        "mapped_seed_exact_gain_upper_bound": float(exact_gain_upper_bound),
        "energy_comparison_width": comparison_width,
        "ordinary_certificate_suppression_scope": (
            "same_physical_state_fingerprint_and_record_id_only"
        ),
        "mapping_or_numerical_failure": False,
    }


def _sr_contradicted_ordinary_record_ids(
    history: Sequence[Mapping[str, Any]],
    *,
    state_fingerprint: str,
) -> frozenset[str]:
    """Return ordinary record IDs retired at one exact physical state."""

    return frozenset(
        str(receipt.get("record_id"))
        for receipt in history
        if isinstance(receipt, Mapping)
        and str(receipt.get("schema", ""))
        == _SR_ORDINARY_MODEL_LIVE_RECEIPT_SCHEMA
        and str(receipt.get("state_fingerprint", ""))
        == str(state_fingerprint)
        and str(receipt.get("model_status_after", "")) == "contradicted"
        and str(receipt.get("record_id", ""))
    )


def _sr_escape_phase1_evaluation_population(
    phase1_records: Sequence[Mapping[str, Any]],
    ordinary_shortlist_records: Sequence[Mapping[str, Any]],
    *,
    active: bool,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Keep the ordinary shortlist literal while exposing all valid Phase-I rows.

    The returned records carry an immutable boolean ancestry tag through the
    existing Phase-II evaluator.  Escape mode is finite eager service: cost
    affects telemetry/order downstream but no Phase-I gradient/score cap may
    remove a valid record before its Phase-III inertia is known.
    """

    ordinary_keys = {
        _batch_admission_record_key(record)
        for record in ordinary_shortlist_records
    }
    source_records = (
        [dict(record) for record in phase1_records]
        if active
        else [dict(record) for record in ordinary_shortlist_records]
    )
    source_keys = [_batch_admission_record_key(record) for record in source_records]
    if len(source_keys) != len(set(source_keys)):
        raise RuntimeError(
            "SR escape Phase-I reachable population contains duplicate record ids."
        )
    missing_ordinary = sorted(ordinary_keys - set(source_keys))
    if missing_ordinary:
        raise RuntimeError(
            "SR escape Phase-I population lost ordinary-shortlist records: "
            f"{missing_ordinary}"
        )
    tagged = [
        {
            **dict(record),
            "sr_escape_phase1_reachable": bool(active),
            "sr_escape_ordinary_phase1_eligible": bool(
                _batch_admission_record_key(record) in ordinary_keys
            ),
        }
        for record in source_records
    ]
    return tagged, {
        "schema": "sr_escape_phase1_eager_finite_population_v1",
        "active": bool(active),
        "service_policy": (
            "complete_finite_eager_no_gradient_gate_v1"
            if active
            else "ordinary_shortlist_only"
        ),
        "raw_record_count": int(len(phase1_records)),
        "ordinary_shortlist_count": int(len(ordinary_shortlist_records)),
        "escape_evaluation_count": int(len(tagged)),
        "zero_gradient_gate_applied": False if active else None,
        "population_complete": bool(active),
    }


def _sr_escape_ordered_phase3_population(
    records: Sequence[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], tuple[str, ...]]:
    """Validate and freeze the deterministic finite Phase-III audit order."""

    rows = sorted(
        (dict(record) for record in records),
        key=_sr_escape_record_id_for_mapping,
    )
    record_ids = tuple(_sr_escape_record_id_for_mapping(record) for record in rows)
    if len(record_ids) != len(set(record_ids)):
        raise RuntimeError(
            "SR escape Phase-III reachable population contains duplicate record ids."
        )
    return rows, record_ids


def _sr_escape_runtime_split_successor_population(
    *,
    parent_record: Mapping[str, Any],
    split_child_set_entries: Sequence[Mapping[str, Any]],
    active: bool,
    runtime_split_required: bool,
) -> list[dict[str, Any]]:
    """Return the complete fixed-Phi successor set for one Phase-I record.

    A non-split record maps to itself.  Under the archival singleton-child
    profile, the parent is only provenance: every validity-gated child-set
    successor must carry a full record into the escape audit, including a
    successor whose ordinary score is zero.  Missing full evaluations fail
    closed instead of silently collapsing to the ordinary best child.
    """

    if not active:
        return []
    if not runtime_split_required:
        return [dict(parent_record)]

    successors: list[dict[str, Any]] = []
    for entry in split_child_set_entries:
        if not isinstance(entry, Mapping):
            raise RuntimeError(
                "SR escape runtime-split successor entry is not a mapping."
            )
        record = entry.get("record")
        if not isinstance(record, Mapping):
            raise RuntimeError(
                "SR escape runtime-split successor lacks its full Phase-II "
                "evaluation."
            )
        successors.append(dict(record))

    ordered, _record_ids = _sr_escape_ordered_phase3_population(successors)
    return ordered


def _sr_escape_runtime_split_record_domains(
    *,
    parent_record: Mapping[str, Any],
    ordered_ordinary_variants: Sequence[Mapping[str, Any]],
    split_child_set_entries: Sequence[Mapping[str, Any]],
    escape_active: bool,
    runtime_split_required: bool,
    ordinary_runtime_split_required: bool,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Separate unchanged ordinary forwarding from exhaustive escape audit."""

    ordinary_domain = (
        [dict(record) for record in ordered_ordinary_variants]
        if ordinary_runtime_split_required
        else [dict(parent_record)]
    )
    ordinary_selected = ordinary_domain[:1]
    escape_successors = _sr_escape_runtime_split_successor_population(
        parent_record=parent_record,
        split_child_set_entries=split_child_set_entries,
        active=bool(escape_active),
        runtime_split_required=bool(runtime_split_required),
    )
    return ordinary_selected, escape_successors


def _sr_escape_phase_controller_service_contract(
    *,
    phase2_enabled: bool,
    phase3_enabled: bool,
    ordinary_phase2_live: bool,
    ordinary_phase3_live: bool,
    ordinary_phase1_terminal_usable: bool,
    escape_active: bool,
) -> dict[str, bool]:
    """Keep literal ordinary phase liveness separate from escape service."""

    escape_phase2_live = bool(ordinary_phase2_live)
    escape_phase3_live = bool(ordinary_phase3_live)
    if escape_active and not ordinary_phase1_terminal_usable:
        escape_phase2_live = bool(phase2_enabled)
        escape_phase3_live = bool(phase3_enabled and escape_phase2_live)
    return {
        "ordinary_phase2_live": bool(ordinary_phase2_live),
        "ordinary_phase3_live": bool(ordinary_phase3_live),
        "ordinary_phase1_terminal_usable": bool(
            ordinary_phase1_terminal_usable
        ),
        "escape_phase2_service_live": bool(escape_phase2_live),
        "escape_phase3_service_live": bool(escape_phase3_live),
        "ordinary_phase_controller_overridden": bool(
            escape_phase2_live != bool(ordinary_phase2_live)
            or escape_phase3_live != bool(ordinary_phase3_live)
        ),
    }


def _sr_escape_rescore_phase2_domains(
    ordinary_and_escape_antecedent_records: Sequence[Mapping[str, Any]],
    escape_successor_records: Sequence[Mapping[str, Any]],
    *,
    cfg: Any,
    active: bool,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Normalize ordinary and escape cost families independently."""

    ordinary_input = [
        dict(record)
        for record in ordinary_and_escape_antecedent_records
        if (
            not active
            or bool(
                record.get("sr_escape_ordinary_phase1_eligible", False)
            )
        )
    ]
    ordinary_scored = rescore_hardware_cost_family(ordinary_input, cfg)
    escape_scored = (
        rescore_hardware_cost_family(
            [dict(record) for record in escape_successor_records],
            cfg,
        )
        if active
        else []
    )
    return (
        [dict(record) for record in ordinary_scored],
        [dict(record) for record in escape_scored],
    )


def _historical_singleton_trust_update_inputs(
    feature_row: Mapping[str, Any],
    *,
    whitening_active: bool,
    sr_escape_active: bool = False,
    coordinate_solve_policy: str = (
        JOINT_LINEAR_SOLVE_SUPPORTED_METRIC_WHITENED_EIGH_V1
    ),
    radius: float,
    metric_floor: float,
    reduced_metric_collapse_rel_tol: float,
) -> tuple[dict[str, Any], str, bool]:
    """Resolve the active coordinate model used by adaptive trust."""

    if bool(whitening_active):
        selector_summary_raw = feature_row.get("phase2_joint_geometry_reuse")
        if not (
            isinstance(selector_summary_raw, Mapping)
            and str(selector_summary_raw.get("schema", ""))
            == HISTORICAL_SINGLETON_COORDINATE_MODEL_SCHEMA
        ):
            selector_summary_raw = feature_row.get(
                "historical_singleton_phase2_coordinate_model"
            )
        if not isinstance(selector_summary_raw, Mapping):
            raise RuntimeError(
                "Whitened historical singleton admission is missing its "
                "coordinate-model summary."
            )
        selector_summary = dict(selector_summary_raw)
        ordinary_escape_selection = bool(
            sr_escape_active
            and str(feature_row.get("sr_escape_decision_kind", ""))
            == "ordinary"
        )
        if ordinary_escape_selection:
            ordinary_summary_raw = selector_summary.get(
                "sr_escape_ordinary_summary"
            )
            if not isinstance(ordinary_summary_raw, Mapping):
                raise RuntimeError(
                    "SR ordinary trust update is missing its preserved v1 "
                    "coordinate-model summary."
                )
            selector_summary = dict(ordinary_summary_raw)
        schema = str(selector_summary.get("schema", ""))
        if schema != HISTORICAL_SINGLETON_COORDINATE_MODEL_SCHEMA:
            raise RuntimeError(
                "Whitened historical singleton trust update received the "
                f"wrong coordinate-model schema: {schema!r}."
            )
        effective_policy = str(
            selector_summary.get("joint_linear_solve_policy_effective", "")
        )
        expected_policy = (
            JOINT_LINEAR_SOLVE_SUPPORTED_METRIC_WHITENED_EIGH_V1
            if ordinary_escape_selection
            else str(coordinate_solve_policy).strip().lower()
        )
        if effective_policy != expected_policy:
            raise RuntimeError(
                "Whitened historical singleton trust update received the "
                "wrong linear-solve policy: "
                f"expected {expected_policy!r}, got {effective_policy!r}."
            )
        if not bool(selector_summary.get("feasible", False)):
            raise RuntimeError(
                "Whitened historical singleton trust update received an "
                "infeasible energy-model summary outside geometry-expansion "
                f"mode: {selector_summary.get('reason', 'unknown')!r}."
            )
        context_mode = str(
            selector_summary.get(
                "joint_batch_context_mode",
                BATCH_JOINT_CONTEXT_FULL_ANSATZ_V1,
            )
        )
        if context_mode != BATCH_JOINT_CONTEXT_FULL_ANSATZ_V1:
            raise RuntimeError(
                "Whitened historical singleton trust update requires the "
                "recorded full-ansatz coordinate model."
            )
        return selector_summary, context_mode, False

    selector_summary = historical_singleton_scalar_selector_summary(
        feature_row,
        radius=float(radius),
        metric_floor=float(metric_floor),
        reduced_metric_collapse_rel_tol=float(
            reduced_metric_collapse_rel_tol
        ),
    )
    return (
        selector_summary,
        HISTORICAL_SINGLETON_SCALAR_TRUST_CONTEXT_V1,
        True,
    )


def _accepted_sr_v2_joint_coordinate_step(
    *,
    selector_summary: Mapping[str, Any],
    pre_parameter_count: int,
    positions_in_commit_order: Sequence[int],
    theta_before_refit: np.ndarray,
    theta_after_refit: np.ndarray,
    post_layout: Any,
) -> list[float] | None:
    """Map an accepted refit into the certified v2 joint-coordinate order."""

    if str(
        selector_summary.get("joint_linear_solve_policy_effective", "")
    ) != JOINT_LINEAR_SOLVE_SUPPORTED_METRIC_GLOBAL_TRUST_EIGH_V2:
        return None
    workspace = selector_summary.get("geometry_workspace")
    if not isinstance(workspace, Mapping):
        raise RuntimeError(
            "SR v2 accepted-path trust transaction is missing its geometry "
            "workspace."
        )
    active_pre_indices = _selector_int_list(
        workspace.get("active_indices", [])
    )
    G_AA = np.asarray(selector_summary.get("G_AA_raw", []), dtype=float)
    G_BB = np.asarray(selector_summary.get("G_BB_raw", []), dtype=float)
    if (
        G_AA.ndim != 2
        or G_AA.shape[0] != G_AA.shape[1]
        or G_BB.ndim != 2
        or G_BB.shape[0] != G_BB.shape[1]
        or len(active_pre_indices) != int(G_AA.shape[0])
        or len(positions_in_commit_order) != int(G_BB.shape[0])
    ):
        raise RuntimeError(
            "SR v2 accepted-path coordinates do not match the certified "
            "metric blocks."
        )
    batch_window = build_composed_batch_window_payload(
        pre_parameter_count=int(pre_parameter_count),
        positions_in_commit_order=[
            int(value) for value in positions_in_commit_order
        ],
        old_pre_indices=active_pre_indices,
    )
    old_post_indices = _selector_int_list(
        batch_window.get("old_post_indices", [])
    )
    candidate_post_indices = _selector_int_list(
        batch_window.get("candidate_post_indices", [])
    )
    canonical_logical = np.asarray(
        _logical_theta_alias(theta_before_refit, post_layout), dtype=float
    ).reshape(-1)
    accepted_logical = np.asarray(
        _logical_theta_alias(theta_after_refit, post_layout), dtype=float
    ).reshape(-1)
    if (
        canonical_logical.size != accepted_logical.size
        or canonical_logical.size
        != int(batch_window.get("post_parameter_count", -1))
    ):
        raise RuntimeError(
            "SR v2 accepted-path refit uses an incompatible logical layout."
        )
    coordinate_order = [*old_post_indices, *candidate_post_indices]
    realized = np.asarray(
        [
            float(accepted_logical[index] - canonical_logical[index])
            for index in coordinate_order
        ],
        dtype=float,
    )
    if not np.all(np.isfinite(realized)):
        raise RuntimeError(
            "SR v2 accepted-path joint coordinate step must be finite."
        )
    return [float(value) for value in realized.tolist()]


def _historical_singleton_admission_coordinate_summary(
    feature_row: Mapping[str, Any],
    coordinate_summary: Mapping[str, Any],
    *,
    sr_escape_active: bool,
) -> dict[str, Any]:
    """Resolve the coordinate model authoritative for admission guards."""

    ordinary_escape_selection = bool(
        sr_escape_active
        and bool(feature_row.get("sr_escape_admission_eligible", False))
        and str(feature_row.get("sr_escape_decision_kind", "")) == "ordinary"
    )
    if not ordinary_escape_selection:
        return dict(coordinate_summary)
    ordinary_summary_raw = coordinate_summary.get("sr_escape_ordinary_summary")
    if not isinstance(ordinary_summary_raw, Mapping):
        raise RuntimeError(
            "SR ordinary admission is missing its preserved v1 "
            "coordinate-model summary."
        )
    ordinary_summary = dict(ordinary_summary_raw)
    if str(ordinary_summary.get("schema", "")) != (
        HISTORICAL_SINGLETON_COORDINATE_MODEL_SCHEMA
    ):
        raise RuntimeError(
            "SR ordinary admission received the wrong preserved v1 "
            "coordinate-model schema."
        )
    if str(
        ordinary_summary.get("joint_linear_solve_policy_effective", "")
    ) != JOINT_LINEAR_SOLVE_SUPPORTED_METRIC_WHITENED_EIGH_V1:
        raise RuntimeError(
            "SR ordinary admission received the wrong preserved v1 "
            "linear-solve policy."
        )
    return ordinary_summary


def _historical_singleton_coordinate_admission_domain(
    records: Sequence[Mapping[str, Any]],
    *,
    rescore_summary: Mapping[str, Any],
    coordinate_solve_policy: str = (
        JOINT_LINEAR_SOLVE_SUPPORTED_METRIC_WHITENED_EIGH_V1
    ),
    sr_escape_active: bool = False,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Resolve the admissible whitened singleton domain before beam planning.

    A mixed coordinate-model population has a usable energy model, so records
    whose model failed the rank/solve gate are diagnostic rows only.  The one
    intentional exception is the all-infeasible geometry-expansion state,
    where every row was explicitly rescored by collective novelty over cost.
    """

    geometry_expansion_active = bool(
        rescore_summary.get("geometry_expansion_active", False)
    )
    kept: list[dict[str, Any]] = []
    rejected: list[dict[str, Any]] = []
    feasible_count = 0
    for ordinal, raw_record in enumerate(records):
        record = dict(raw_record)
        feature = record.get("feature")
        if not isinstance(feature, CandidateFeatures):
            raise RuntimeError(
                "Historical singleton coordinate admission requires "
                "CandidateFeatures on every rescored record."
            )
        coordinate_summary = dict(feature.phase2_joint_geometry_reuse or {})
        if str(coordinate_summary.get("schema", "")) != (
            HISTORICAL_SINGLETON_COORDINATE_MODEL_SCHEMA
        ):
            raise RuntimeError(
                "Historical singleton coordinate admission received the wrong "
                "coordinate-model schema."
            )
        if str(
            coordinate_summary.get("joint_linear_solve_policy_effective", "")
        ) != str(coordinate_solve_policy).strip().lower():
            raise RuntimeError(
                "Historical singleton coordinate admission received the wrong "
                "linear-solve policy."
            )
        base_feasible = bool(coordinate_summary.get("feasible", False))
        if bool(
            record.get("phase3_coordinate_model_feasible", base_feasible)
        ) != base_feasible:
            raise RuntimeError(
                "Historical singleton coordinate feasibility telemetry disagrees "
                "with its typed coordinate-model summary."
            )
        admission_summary = _historical_singleton_admission_coordinate_summary(
            record,
            coordinate_summary,
            sr_escape_active=bool(sr_escape_active),
        )
        feasible = bool(admission_summary.get("feasible", False))
        feasible_count += int(feasible)
        try:
            full_score = float(record.get("full_v2_score", float("nan")))
        except (TypeError, ValueError):
            full_score = float("nan")
        identity = {
            "input_ordinal": int(ordinal),
            "candidate_pool_index": int(record.get("candidate_pool_index", -1)),
            "position_id": int(record.get("position_id", -1)),
            "candidate_label": str(record.get("candidate_label", "")),
            "coordinate_model_reason": str(
                admission_summary.get("reason", "unknown")
            ),
        }
        if bool(sr_escape_active):
            if geometry_expansion_active:
                raise RuntimeError(
                    "SR escape admission cannot use numerical geometry expansion."
                )
            if bool(record.get("sr_escape_admission_eligible", False)):
                if not feasible or not math.isfinite(full_score):
                    raise RuntimeError(
                        "SR escape marked an infeasible or nonfinite record "
                        "eligible for singleton admission."
                    )
                kept.append(record)
                continue
            rejected.append(
                {
                    **identity,
                    "reason": "sr_escape_controller_not_admission_eligible",
                }
            )
            continue
        if geometry_expansion_active:
            if feasible:
                raise RuntimeError(
                    "Geometry expansion cannot be active while a whitened "
                    "energy model is feasible."
                )
            if str(record.get("route_a_geometry_expansion_mode", "")) != (
                "collective_span_novelty_over_cost_v1"
            ):
                raise RuntimeError(
                    "All-infeasible geometry expansion is missing its explicit "
                    "novelty admission marker."
                )
            if not math.isfinite(full_score):
                raise RuntimeError(
                    "Geometry-expansion novelty admission requires a finite score."
                )
            kept.append(record)
            continue
        if feasible and math.isfinite(full_score):
            kept.append(record)
            continue
        rejected.append(
            {
                **identity,
                "reason": (
                    "nonfinite_coordinate_score"
                    if feasible
                    else "infeasible_coordinate_energy_model"
                ),
            }
        )

    if geometry_expansion_active and feasible_count != 0:
        raise RuntimeError(
            "Geometry-expansion admission domain contains a feasible energy model."
        )
    if (
        records
        and not bool(sr_escape_active)
        and not geometry_expansion_active
        and feasible_count > 0
        and not kept
    ):
        raise RuntimeError(
            "Whitened coordinate admission lost every feasible finite-score row."
        )
    telemetry = {
        "schema": "historical_singleton_coordinate_admission_domain_v1",
        "policy": (
            "sr_escape_controller_eligible_singletons_only_v1"
            if bool(sr_escape_active)
            else (
                "all_infeasible_collective_novelty_v1"
                if geometry_expansion_active
                else "feasible_energy_models_only_v1"
            )
        ),
        "coordinate_solve_policy": str(coordinate_solve_policy),
        "sr_escape_active": bool(sr_escape_active),
        "geometry_expansion_active": bool(geometry_expansion_active),
        "input_count": int(len(records)),
        "feasible_count": int(feasible_count),
        "kept_count": int(len(kept)),
        "filtered_count": int(len(rejected)),
        "filtered_records": rejected,
        "membership_filter_applied": bool(rejected),
    }
    return kept, telemetry


def _assert_historical_singleton_coordinate_plan_admissible(
    feature_row: Mapping[str, Any],
    *,
    whitening_active: bool,
    coordinate_solve_policy: str = (
        JOINT_LINEAR_SOLVE_SUPPORTED_METRIC_WHITENED_EIGH_V1
    ),
    sr_escape_active: bool = False,
    allow_query_closed_finite_angle_bridge: bool = False,
) -> None:
    """Fail before ansatz mutation if a stale plan bypassed the domain gate."""

    if not bool(whitening_active):
        return
    finite_angle_bridge = feature_row.get(
        "formal_manifold_finite_angle_fallback_bridge"
    )
    if bool(allow_query_closed_finite_angle_bridge) and isinstance(
        finite_angle_bridge, Mapping
    ):
        if (
            str(finite_angle_bridge.get("schema", ""))
            != "formal_manifold_query_closed_finite_angle_bridge_v1"
            or not bool(finite_angle_bridge.get("recompute_supported_geometry", False))
            or not bool(finite_angle_bridge.get("exact_zero_growth", False))
        ):
            raise RuntimeError(
                "FM+SR finite-angle fallback has a malformed query-closed growth bridge."
            )
        return
    coordinate_summary_raw = feature_row.get("phase2_joint_geometry_reuse")
    if not (
        isinstance(coordinate_summary_raw, Mapping)
        and str(coordinate_summary_raw.get("schema", ""))
        == HISTORICAL_SINGLETON_COORDINATE_MODEL_SCHEMA
    ):
        coordinate_summary_raw = feature_row.get(
            "historical_singleton_phase2_coordinate_model"
        )
    if not isinstance(coordinate_summary_raw, Mapping):
        raise RuntimeError(
            "Whitened historical singleton plan lacks a coordinate-model summary."
        )
    coordinate_summary = dict(coordinate_summary_raw)
    if str(coordinate_summary.get("schema", "")) != (
        HISTORICAL_SINGLETON_COORDINATE_MODEL_SCHEMA
    ):
        raise RuntimeError(
            "Whitened historical singleton plan has the wrong coordinate schema."
        )
    if str(
        coordinate_summary.get("joint_linear_solve_policy_effective", "")
    ) != str(coordinate_solve_policy).strip().lower():
        raise RuntimeError(
            "Whitened historical singleton plan has the wrong solve policy."
        )
    if bool(sr_escape_active) and not bool(
        feature_row.get("sr_escape_admission_eligible", False)
    ):
        raise RuntimeError(
            "SR escape plan bypassed the controller admission gate."
        )
    admission_summary = _historical_singleton_admission_coordinate_summary(
        feature_row,
        coordinate_summary,
        sr_escape_active=bool(sr_escape_active),
    )
    if bool(admission_summary.get("feasible", False)):
        return
    if not bool(sr_escape_active) and str(
        feature_row.get("route_a_geometry_expansion_mode", "")
    ) == (
        "collective_span_novelty_over_cost_v1"
    ):
        return
    raise RuntimeError(
        "Whitened historical singleton plan carries an infeasible energy model "
        "outside explicit all-infeasible geometry-expansion mode."
    )


_RUNTIME_SPLIT_FIXED_PARTICLE_PROBLEMS = frozenset(
    {
        "hh",
        "hubbard",
        "molecular_restricted_closed_shell",
        "molecular_vibronic_h2o_linear_fd",
    }
)


def _runtime_split_fixed_num_particles(
    *,
    problem_key: str,
    num_particles: Sequence[int],
) -> tuple[int, ...] | None:
    if str(problem_key).strip().lower() not in _RUNTIME_SPLIT_FIXED_PARTICLE_PROBLEMS:
        return None
    return tuple(int(value) for value in num_particles)


def _runtime_split_admission_guard_contract_satisfied(
    *,
    symmetry_gate: Mapping[str, Any],
    expected_fixed_num_particles: Sequence[int] | None,
) -> bool:
    """Validate an executed hard guard against the active problem sector."""

    if expected_fixed_num_particles is None:
        return False
    expected_counts = tuple(int(value) for value in expected_fixed_num_particles)
    if len(expected_counts) != 2:
        return False
    fixed_sector = symmetry_gate.get("fixed_count_sector")
    fixed_sector = fixed_sector if isinstance(fixed_sector, Mapping) else {}
    fixed_counts = fixed_sector.get("fixed_num_particles")
    fixed_counts = fixed_counts if isinstance(fixed_counts, Mapping) else {}
    try:
        actual_counts = (
            int(fixed_counts.get("n_up", -1)),
            int(fixed_counts.get("n_dn", -1)),
        )
    except (TypeError, ValueError):
        return False
    return bool(
        symmetry_gate.get("checked", False)
        and symmetry_gate.get("passed", False)
        and symmetry_gate.get("gate_scope")
        == "fixed_count_sector_invariance_v1"
        and symmetry_gate.get("skipped_reason") in {None, ""}
        and actual_counts == expected_counts
    )


def _historical_singleton_child_padding_contract(
    *,
    problem_key: str,
    boson_encoding: str,
    n_ph_max: int,
    projection_active: bool,
) -> dict[str, Any]:
    if bool(projection_active):
        return {
            "satisfied": True,
            "source": "exact_projected_grouped_v1",
            "projection_active": True,
        }
    fermion_only_no_padding = bool(
        str(problem_key).strip().lower()
        == "molecular_restricted_closed_shell"
    )
    h2o_full_binary_code_space = bool(
        str(problem_key).strip().lower()
        == "molecular_vibronic_h2o_linear_fd"
        and str(boson_encoding).strip().lower() == "binary"
        and int(n_ph_max) == 1
    )
    return {
        "satisfied": bool(fermion_only_no_padding or h2o_full_binary_code_space),
        "source": (
            "fermion_only_no_binary_padding_v1"
            if fermion_only_no_padding
            else (
                "h2o_linear_fd_nph1_full_binary_code_space_v1"
                if h2o_full_binary_code_space
                else "unsatisfied"
            )
        ),
        "projection_active": False,
    }


def _historical_paper_i_route_compatibility_active(
    *,
    problem_key: str,
    static_route_id_key: str,
    static_meta_feature_profile: str,
    static_lane_route_key: str,
    route_a_funnel_active: bool,
    adapt_pool: str | None,
    adapt_continuation_mode: str,
    phase2_enable_batching: bool,
    phase3_enable_batching: bool,
    phase3_runtime_split_mode: str,
    phase3_runtime_split_selection_mode: str,
    phase3_runtime_split_max_subset_size: int,
    phase3_runtime_split_subset_sizes: str | Sequence[int] | None,
    physical_lane_shortlist_factor: int,
    phase1_shortlist_size_base: int,
    phase2_shortlist_size_base: int,
    phase2_shortlist_fraction_base: float,
) -> bool:
    exact_subset_sizes = (
        normalize_runtime_split_subset_sizes(phase3_runtime_split_subset_sizes)
        if phase3_runtime_split_subset_sizes is not None
        else (1,)
    )
    return bool(
        str(static_route_id_key) == ROUTE_ID_A
        and normalize_static_meta_feature_profile(static_meta_feature_profile)
        == STATIC_META_FEATURE_PROFILE_PAPER_I_PRODUCTION_V1
        and str(static_lane_route_key)
        == STATIC_LANE_ROUTE_PHYSICAL_OPERATOR_TYPE
        and not bool(route_a_funnel_active)
        and (
            str(adapt_pool or "").strip().lower() == "full_meta"
            or (
                str(problem_key).strip().lower()
                == "molecular_restricted_closed_shell"
                and str(adapt_pool or "").strip().lower() == "uccsd"
            )
        )
        and str(adapt_continuation_mode).strip().lower() == "phase3_v1"
        and not bool(phase2_enable_batching)
        and not bool(phase3_enable_batching)
        and str(phase3_runtime_split_mode).strip().lower()
        == "shortlist_pauli_children_v1"
        and str(phase3_runtime_split_selection_mode).strip().lower()
        == "archival_child_set_forward_v1"
        and int(phase3_runtime_split_max_subset_size) == 1
        and tuple(int(value) for value in exact_subset_sizes) == (1,)
        and int(physical_lane_shortlist_factor) == 3
        and int(phase1_shortlist_size_base) == 24
        and int(phase2_shortlist_size_base) == 12
        and float(phase2_shortlist_fraction_base) == 0.25
    )


def _validate_resolved_static_route_identity(
    payload: Mapping[str, Any],
    *,
    declared_route_id: str,
    historical_singleton_overlay_active: bool,
    route_profile_conformance: str | None = None,
    phase2_gram_novelty_policy: str = (
        GRAM_NOVELTY_POLICY_ORDINARY_MULTIPLIER_V1
    ),
    phase3_gram_novelty_policy: str = (
        GRAM_NOVELTY_POLICY_ORDINARY_MULTIPLIER_V1
    ),
    sr_controller_ablation_contract: str = (
        SR_CONTROLLER_ABLATION_CONTRACT_OFF
    ),
    phase1_prune_enabled: bool = True,
    phase1_prune_mode: str = "both",
) -> dict[str, Any]:
    """Validate legacy route fields without rejecting an explicit SR ablation."""

    if not bool(historical_singleton_overlay_active):
        validate_declared_static_route_identity(
            payload,
            declared_route_id=declared_route_id,
        )
        return {
            "schema": "resolved_static_route_validation_v1",
            "route_family": None,
            "valid": bool(payload.get("valid", False)),
            "allowed_legacy_noncanonical_reasons": [],
        }

    reasons = [str(value) for value in payload.get("noncanonical_reasons", ())]
    allowed_prefixes = list(_SR_ALLOWED_LEGACY_ROUTE_REASON_PREFIXES)
    controller_ablation_contract_key = str(
        sr_controller_ablation_contract
    ).strip().lower()
    if (
        controller_ablation_contract_key
        not in SR_CONTROLLER_ABLATION_CONTRACT_CHOICES
    ):
        raise ValueError(
            "sr_controller_ablation_contract must be one of "
            f"{list(SR_CONTROLLER_ABLATION_CONTRACT_CHOICES)}."
        )
    profile_instance_ablation = bool(
        str(route_profile_conformance or "").strip().lower()
        == SR_ROUTE_PROFILE_CONFORMANCE_UNPROMOTED_EXPLICIT_ABLATION
    )
    controller_ablation_marked = bool(
        controller_ablation_contract_key
        in {
            SR_CONTROLLER_ABLATION_CONTRACT_NOVELTY_PRUNE_CONTROLS_V1,
            SR_CONTROLLER_ABLATION_CONTRACT_NOVELTY_PRUNE_BEAM_CONTROLS_V1,
        }
    )
    explicit_ablation = bool(
        profile_instance_ablation or controller_ablation_marked
    )
    novelty_fallback_ablation = bool(
        explicit_ablation
        and str(phase2_gram_novelty_policy).strip().lower()
        == GRAM_NOVELTY_POLICY_FALLBACK_ONLY_V1
        and str(phase3_gram_novelty_policy).strip().lower()
        == GRAM_NOVELTY_POLICY_FALLBACK_ONLY_V1
    )
    if novelty_fallback_ablation:
        allowed_prefixes.append("mismatch:phase2_raw_score_formula:")
    if explicit_ablation and not bool(phase1_prune_enabled):
        allowed_prefixes.extend(
            (
                "mismatch:phase1_prune_enabled:",
                "mismatch:phase1_prune_mode:",
            )
        )
    elif explicit_ablation and str(phase1_prune_mode).strip().lower() == "live":
        allowed_prefixes.append("mismatch:phase1_prune_mode:")
    allowed = [
        reason
        for reason in reasons
        if reason.startswith(tuple(allowed_prefixes))
    ]
    unsupported = [reason for reason in reasons if reason not in allowed]
    if unsupported:
        raise ValueError(
            "Resolved SR-SNAKE profile does not match its required legacy "
            "controller contract: " + "; ".join(unsupported)
        )
    return {
        "schema": "resolved_static_route_validation_v1",
        "route_family": str(SR_ROUTE_FAMILY),
        "valid": True,
        "allowed_legacy_noncanonical_reasons": list(allowed),
        "validation_authority": (
            "sr_explicit_ablation_contract_v1"
            if explicit_ablation
            else "sr_registered_profile_legacy_contract_v1"
        ),
        "explicit_ablation": bool(explicit_ablation),
        "profile_instance_ablation": bool(profile_instance_ablation),
        "controller_ablation_marked": bool(controller_ablation_marked),
        "sr_controller_ablation_contract": str(
            controller_ablation_contract_key
        ),
        "novelty_fallback_ablation": bool(novelty_fallback_ablation),
    }


def _resolve_sr_powell_coordinate_chart_runtime_policy(
    *,
    historical_singleton_overlay_active: bool,
    sr_escape_mode: SREscapeMode | str,
    coordinate_solve_scope: str,
    requested_policy: str,
    source_locked_replay: bool,
    formal_manifold_selector_profile: str | None = None,
    formal_manifold_required_coordinate_solve_scope: str | None = None,
) -> dict[str, Any]:
    """Resolve an explicit runtime chart without changing non-SR defaults.

    Canonical SR-SNAKE v1 owns the historical expanded Powell chart.  Newer
    SR profiles name the reduced chart explicitly.  Generic static-ADAPT
    callers retain the reduced chart for compatibility, and source-locked SR
    replay is never allowed to infer a missing chart from ``auto``.
    """

    requested = str(requested_policy).strip().lower()
    if requested not in SR_POWELL_COORDINATE_CHART_REQUEST_CHOICES:
        raise ValueError(
            "sr_powell_coordinate_chart_policy must be one of "
            f"{list(SR_POWELL_COORDINATE_CHART_REQUEST_CHOICES)}."
        )
    overlay_active = bool(historical_singleton_overlay_active)
    if (
        overlay_active
        and bool(source_locked_replay)
        and requested == SR_POWELL_COORDINATE_CHART_AUTO
    ):
        raise ValueError(
            "Source-locked SR-SNAKE replay requires an explicit "
            "--sr-powell-coordinate-chart-policy; refusing to infer a "
            "historical optimizer chart."
        )
    if not overlay_active and requested != SR_POWELL_COORDINATE_CHART_AUTO:
        raise ValueError(
            "An explicit SR Powell coordinate-chart policy requires an "
            "active SR-SNAKE coordinate/trust overlay."
        )

    route_instance: dict[str, Any] | None = None
    if formal_manifold_selector_profile is not None:
        required_scope = str(
            formal_manifold_required_coordinate_solve_scope
            or SR_COORDINATE_SOLVE_SCOPE_PHASE2_AND_PHASE3_V1
        ).strip().lower()
        if (
            not overlay_active
            or requested
            != SR_POWELL_COORDINATE_CHART_EXPANDED_RUNTIME_PROJECTED_LOGICAL_V1
            or str(coordinate_solve_scope).strip().lower()
            != required_scope
            or SREscapeMode(sr_escape_mode) is not SREscapeMode.DISABLED
        ):
            raise ValueError(
                "The FM+SR selector profile requires the explicit expanded-runtime "
                f"Powell chart, coordinate scope {required_scope!r}, and disabled escape."
            )
        resolved_sr_policy = str(requested)
        route_profile_conformance = "registered_profile"
    else:
        route_instance = dict(
            resolve_sr_powell_route_instance(
                sr_escape_mode,
                coordinate_solve_scope=str(coordinate_solve_scope),
                requested_policy=requested,
            )
        )
        resolved_sr_policy = str(
            route_instance["powell_coordinate_chart_policy"]
        )
        route_profile_conformance = str(
            route_instance["route_profile_conformance"]
        )
    runtime_policy = str(
        resolved_sr_policy
        if overlay_active
        else SR_POWELL_COORDINATE_CHART_LOGICAL_SHARED_REDUCED_V1
    )
    profile = (
        str(formal_manifold_selector_profile)
        if formal_manifold_selector_profile is not None
        else str(route_instance["route_profile"])
    )
    return {
        "schema": "sr_powell_coordinate_chart_resolution_v1",
        "overlay_active": bool(overlay_active),
        "requested_policy": str(requested),
        "resolved_sr_policy": str(resolved_sr_policy),
        "runtime_policy": str(runtime_policy),
        "route_profile": str(profile),
        "route_profile_conformance": str(route_profile_conformance),
        "route_instance": (
            None if route_instance is None else dict(route_instance)
        ),
        "source_locked_replay": bool(source_locked_replay),
        "formal_manifold_selector_profile": formal_manifold_selector_profile,
        "formal_manifold_required_coordinate_solve_scope": (
            formal_manifold_required_coordinate_solve_scope
        ),
        "resolution_source": (
            "canonical_sr_profile_auto"
            if overlay_active and requested == SR_POWELL_COORDINATE_CHART_AUTO
            else (
                "explicit_request"
                if overlay_active
                else "non_sr_compatibility_default"
            )
        ),
    }


def _resolve_physical_lane_shortlist_budget_contract(
    *,
    problem_key: str,
    static_route_id_key: str,
    static_meta_feature_profile: str,
    static_lane_route_key: str,
    route_a_funnel_active: bool,
    adapt_pool: str | None,
    adapt_continuation_mode: str,
    phase2_enable_batching: bool,
    phase3_enable_batching: bool,
    phase3_runtime_split_mode: str,
    phase3_runtime_split_selection_mode: str,
    phase3_runtime_split_max_subset_size: int,
    phase3_runtime_split_subset_sizes: str | Sequence[int] | None,
    physical_lane_shortlist_factor: int,
    phase1_shortlist_size_base: int,
    phase2_shortlist_size_base: int,
    phase2_shortlist_fraction_base: float,
) -> dict[str, Any]:
    """Resolve the source-locked July-8 physical-lane shortlist contract.

    The historical Paper-I physical-lane campaign divided both shortlist caps
    and the Phase-II fraction by the requested aggressiveness factor.  Current
    joint-response funnels own their explicit caps and must not inherit this
    archival adjustment.
    """

    factor = int(physical_lane_shortlist_factor)
    if factor < 1:
        raise ValueError("physical_lane_shortlist_factor must be >= 1.")
    archival_paper_i_contract = (
        _historical_paper_i_route_compatibility_active(
            problem_key=str(problem_key),
            static_route_id_key=str(static_route_id_key),
            static_meta_feature_profile=str(static_meta_feature_profile),
            static_lane_route_key=str(static_lane_route_key),
            route_a_funnel_active=bool(route_a_funnel_active),
            adapt_pool=adapt_pool,
            adapt_continuation_mode=str(adapt_continuation_mode),
            phase2_enable_batching=bool(phase2_enable_batching),
            phase3_enable_batching=bool(phase3_enable_batching),
            phase3_runtime_split_mode=str(phase3_runtime_split_mode),
            phase3_runtime_split_selection_mode=str(
                phase3_runtime_split_selection_mode
            ),
            phase3_runtime_split_max_subset_size=int(
                phase3_runtime_split_max_subset_size
            ),
            phase3_runtime_split_subset_sizes=(
                phase3_runtime_split_subset_sizes
            ),
            physical_lane_shortlist_factor=int(
                physical_lane_shortlist_factor
            ),
            phase1_shortlist_size_base=int(phase1_shortlist_size_base),
            phase2_shortlist_size_base=int(phase2_shortlist_size_base),
            phase2_shortlist_fraction_base=float(
                phase2_shortlist_fraction_base
            ),
        )
    )
    if archival_paper_i_contract:
        phase1_effective = int(
            math.ceil(float(phase1_shortlist_size_base) / float(factor))
        )
        phase2_effective = int(
            math.ceil(float(phase2_shortlist_size_base) / float(factor))
        )
        fraction_effective = float(phase2_shortlist_fraction_base) / float(
            factor
        )
        policy = "paper_i_july8_physical_lane_factor_division_v1"
    else:
        phase1_effective = int(phase1_shortlist_size_base)
        phase2_effective = int(phase2_shortlist_size_base)
        fraction_effective = float(phase2_shortlist_fraction_base)
        policy = "explicit_caps_unchanged_v1"
    return {
        "policy": str(policy),
        "historical_paper_i_contract_active": bool(archival_paper_i_contract),
        "historical_route_compatibility_id": (
            str(_HISTORICAL_PAPER_I_ROUTE_COMPATIBILITY_ID)
            if archival_paper_i_contract
            else None
        ),
        "physical_lane_shortlist_factor": int(factor),
        "phase1_shortlist_size_base": int(phase1_shortlist_size_base),
        "phase1_shortlist_size_effective": int(phase1_effective),
        "phase2_shortlist_size_base": int(phase2_shortlist_size_base),
        "phase2_shortlist_size_effective": int(phase2_effective),
        "phase2_shortlist_fraction_base": float(
            phase2_shortlist_fraction_base
        ),
        "phase2_shortlist_fraction_effective": float(fraction_effective),
    }


def _phase1_full_record_cheap_score_cfg(
    *,
    historical_paper_i_route_compat: bool,
    phase3_enabled: bool,
    phase2_score_cfg: Any,
) -> Any | None:
    """Resolve the Phase-I full-record cheap-score convention.

    The preserved July-8 Paper-I physical singleton route built beam-search
    Phase-I records without a Phase-II cheap-score override.  All other routes
    retain the current convention.
    """

    if bool(historical_paper_i_route_compat):
        return None
    return phase2_score_cfg if bool(phase3_enabled) else None


def _safe_stdout_print(*args: Any, **kwargs: Any) -> bool:
    global _STDOUT_PIPE_BROKEN
    if _STDOUT_PIPE_BROKEN:
        return False
    try:
        print(*args, **kwargs)
        return True
    except BrokenPipeError:
        _STDOUT_PIPE_BROKEN = True
        return False
    except OSError as exc:
        if getattr(exc, "errno", None) == errno.EPIPE:
            _STDOUT_PIPE_BROKEN = True
            return False
        raise


def _ai_log(event: str, **fields: Any) -> None:
    payload = {
        "event": str(event),
        "ts_utc": datetime.now(timezone.utc).isoformat(),
        **fields,
    }
    _safe_stdout_print(f"AI_LOG {json.dumps(payload, sort_keys=True, default=str)}", flush=True)


# ============================================================================
# ADAPT-VQE core — standard algorithm, no meta-learner
# ============================================================================

def _ansatz_terms_require_logical_shared_parameterization(
    terms: Sequence[Any] | None,
) -> bool:
    """Return True when any selected generator needs grouped logical execution."""
    if terms is None:
        return False
    for term in terms:
        execution_mode = str(
            getattr(term, "execution_mode", "termwise_product") or "termwise_product"
        ).strip().lower()
        if execution_mode == "grouped_exact":
            return True
    return False


def _resolve_selected_parameterization_mode(
    *,
    problem_key_value: str,
    pool_key_value: str,
    candidate_terms: Sequence[Any] | None = None,
    sector_contract_requires_logical_shared: bool = False,
) -> str:
    # The executable generator contract is authoritative.  Route/display pool
    # names such as ``phase3_v1`` do not describe whether Pauli components are
    # independent coordinates and must not decide the ansatz parameterization.
    if bool(sector_contract_requires_logical_shared):
        return "logical_shared"
    if _ansatz_terms_require_logical_shared_parameterization(candidate_terms):
        return "logical_shared"
    key = str(problem_key_value).strip().lower()
    pool_key_norm = str(pool_key_value).strip().lower()
    if key in {
        "ionic_hubbard",
        "extended_hubbard",
        "ttprime_hubbard",
        "spinless_tv",
        "spin_boson",
        "bose_hubbard",
        "harmonic_kerr_chain",
    } and pool_key_norm in {
        "hva",
        "hamiltonian_blocks",
        "hamiltonian_quadratures",
        "family_max",
        "full_meta",
    }:
        return "logical_shared"
    if key in {"hubbard", "hh"} and pool_key_norm == "full_meta":
        return "logical_shared"
    if key == "molecular_restricted_closed_shell" and pool_key_norm in {
        "hva",
        "hamiltonian_blocks",
        "family_max",
        "full_meta",
    }:
        return "logical_shared"
    if key in {
        "molecular_vibronic_h2",
        "molecular_vibronic_h2o",
        "molecular_vibronic_h2o_linear_fd",
    } and pool_key_norm in {
        "hva",
        "hamiltonian_blocks",
        "hamiltonian_quadratures",
        "family_max",
        "full_meta",
    }:
        return "logical_shared"
    return "per_pauli_term"


def _apply_rotosolve_parameterization_policy(
    *,
    selected_parameterization_mode: str,
    selected_parameterization_mode_source: str,
    adapt_inner_optimizer_key: str,
    phase3_trial_optimizer: str | None = None,
) -> tuple[str, str]:
    """Prefer per-Pauli ROTOSOLVE coordinates unless the route requires grouping."""
    rotosolve_parameterization_requested = (
        str(adapt_inner_optimizer_key).strip().upper() == "ROTOSOLVE"
        or str(phase3_trial_optimizer or "").strip().upper() == "ROTOSOLVE"
    )
    if not rotosolve_parameterization_requested:
        return selected_parameterization_mode, selected_parameterization_mode_source
    if str(selected_parameterization_mode).strip().lower() == "logical_shared":
        return selected_parameterization_mode, "rotosolve_preserve_logical_shared"
    return "per_pauli_term", "rotosolve_runtime_per_pauli"


def _optimizer_coordinate_chart_payload(
    *,
    layout: AnsatzParameterLayout,
    parameterization_execution_mode: str,
    optimizer_key: str,
    powell_coordinate_chart_policy: str,
) -> dict[str, Any]:
    """Describe the full optimizer chart without changing artifact vectors.

    Runtime vectors remain expanded for checkpoint compatibility.  The
    explicit Powell policy determines whether a ``logical_shared`` ansatz is
    optimized in the historical expanded runtime chart (with block-mean
    projection at every objective boundary) or in the newer reduced chart
    with one coordinate per logical generator.
    """

    execution_mode = str(parameterization_execution_mode).strip().lower()
    optimizer = str(optimizer_key).strip().upper()
    powell_chart_policy = str(powell_coordinate_chart_policy).strip().lower()
    if powell_chart_policy not in SR_POWELL_COORDINATE_CHART_POLICY_CHOICES:
        raise ValueError(
            "powell_coordinate_chart_policy must be one of "
            f"{list(SR_POWELL_COORDINATE_CHART_POLICY_CHOICES)}."
        )
    logical_dimension = int(layout.logical_parameter_count)
    runtime_dimension = int(layout.runtime_parameter_count)
    policy_applied = bool(
        execution_mode == "logical_shared" and optimizer == "POWELL"
    )
    reduced_logical_chart_active = bool(
        policy_applied
        and powell_chart_policy
        == SR_POWELL_COORDINATE_CHART_LOGICAL_SHARED_REDUCED_V1
    )
    expanded_runtime_projected_logical_active = bool(
        policy_applied
        and powell_chart_policy
        == SR_POWELL_COORDINATE_CHART_EXPANDED_RUNTIME_PROJECTED_LOGICAL_V1
    )
    optimizer_dimension = (
        int(logical_dimension)
        if reduced_logical_chart_active
        else int(runtime_dimension)
    )
    return {
        "schema": "static_adapt_optimizer_coordinate_chart_v2",
        "optimizer": str(optimizer),
        "parameterization_execution_mode": str(execution_mode),
        "powell_coordinate_chart_policy": str(powell_chart_policy),
        "powell_coordinate_chart_policy_applied": bool(policy_applied),
        "coordinate_mode": (
            "logical_shared" if reduced_logical_chart_active else "runtime"
        ),
        "optimizer_dimension": int(optimizer_dimension),
        "logical_dimension": int(logical_dimension),
        "runtime_dimension": int(runtime_dimension),
        "one_coordinate_per_logical_generator": bool(
            reduced_logical_chart_active
            and optimizer_dimension == logical_dimension
        ),
        "expanded_runtime_projected_logical": bool(
            expanded_runtime_projected_logical_active
        ),
        "logical_projection_boundary": (
            "block_mean_each_objective_and_lift"
            if expanded_runtime_projected_logical_active
            else (
                "uniform_block_expansion_after_reduced_optimization"
                if reduced_logical_chart_active
                else "not_applicable"
            )
        ),
        "runtime_vector_remains_expanded": True,
    }


