    adapt_drop_floor = float(stop_policy.adapt_drop_floor)
    adapt_drop_patience = int(stop_policy.adapt_drop_patience)
    adapt_drop_min_depth = int(stop_policy.adapt_drop_min_depth)
    adapt_grad_floor = float(stop_policy.adapt_grad_floor)
    drop_policy_enabled = bool(stop_policy.drop_policy_enabled)
    adapt_noise_floor_stop_policy_key = str(adapt_noise_floor_stop_policy or "off").strip().lower() or "off"
    if adapt_noise_floor_stop_policy_key not in {"off", "noise_floor_agreement_v1"}:
        raise ValueError("adapt_noise_floor_stop_policy must be one of {'off','noise_floor_agreement_v1'}.")
    adapt_noise_floor_snr_threshold_val = float(adapt_noise_floor_snr_threshold)
