    def _selector_score_value(row: Mapping[str, Any] | None) -> float:
        if not isinstance(row, Mapping):
            return 0.0
        for key in ("selector_score", "full_v2_score", "phase2_raw_score", "simple_score"):
            raw = row.get(key)
            if raw is None:
                continue
            try:
                return float(raw)
            except (TypeError, ValueError):
                continue
        return 0.0

