    def _phase3_record_sort_key(record: Mapping[str, Any]) -> tuple[float, float, float, int, int]:
        primary_score = record.get(_phase3_selector_score_key(), float("-inf"))
        if primary_score is None:
            primary_score = float("-inf")
        tie_score = record.get(_phase3_selector_tie_break_score_key(), float("-inf"))
        if tie_score is None:
            tie_score = float("-inf")
        secondary_score = record.get(_phase3_selector_secondary_geometry_score_key(), float("-inf"))
        if secondary_score is None:
            secondary_score = float("-inf")
        return (
            -float(primary_score),
            -float(tie_score),
            -float(secondary_score),
            int(record.get("candidate_pool_index", -1)),
            int(record.get("position_id", -1)),
        )

